parts.openscad_module:
$fn = 64;

leaf_length     = 40;
leaf_width      = 20;
leaf_thickness  = 3;
pin_d           = 5;
knuckle_count   = 5;
clearance       = 0.35;

knuckle_l = leaf_length / (2 * knuckle_count - 1);

module hinge_leaf_a() {
  for (i = [0 : knuckle_count - 1]) {
    x = i * 2 * knuckle_l;
    translate([x, 0, 0]) {
      cube([knuckle_l, leaf_width, leaf_thickness]);
      translate([knuckle_l/2, leaf_width/2, leaf_thickness])
        rotate([90, 0, 0])
          cylinder(h = leaf_width, d = pin_d, center = true);
    }
  }
}

module hinge_leaf_b() {
  for (i = [0 : knuckle_count - 2]) {
    x = (i * 2 + 1) * knuckle_l;
    translate([x, 0, leaf_thickness + clearance]) {
      cube([knuckle_l, leaf_width, leaf_thickness]);
      translate([knuckle_l/2, leaf_width/2, 0])
        difference() {
          rotate([90, 0, 0]) cylinder(h = leaf_width + 2, d = pin_d + 4, center = true);
          rotate([90, 0, 0]) cylinder(h = leaf_width + 4, d = pin_d + 2*clearance, center = true);
        }
    }
  }
}

module print_in_place_hinge() {
  hinge_leaf_a();
  hinge_leaf_b();
}

print_in_place_hinge();
